namespace NotificationsApp.Services;

public class Notification
{
    public int Id { get; set; }
    public string Message { get; set; } = "";
    public DateTime Timestamp { get; set; }
}

public class NotificationService
{
    private int _nextId = 1;
    private readonly List<Notification> _notifications = new();
    private readonly Lock _lock = new();

    public NotificationService()
    {
        // Seed with initial fake data
        _notifications.AddRange(new[]
        {
            new Notification { Id = _nextId++, Message = "Welcome to the app!", Timestamp = DateTime.UtcNow.AddMinutes(-30) },
            new Notification { Id = _nextId++, Message = "Your profile was updated.", Timestamp = DateTime.UtcNow.AddMinutes(-15) },
            new Notification { Id = _nextId++, Message = "New feature: dark mode is available.", Timestamp = DateTime.UtcNow.AddMinutes(-5) },
        });

        // Simulate new notifications arriving over time
        _ = GenerateNotificationsAsync();
    }

    public Task<List<Notification>> GetNotificationsAsync()
    {
        lock (_lock)
        {
            return Task.FromResult(_notifications.OrderByDescending(n => n.Timestamp).ToList());
        }
    }

    public Task<List<Notification>> GetNotificationsSinceAsync(int lastSeenId)
    {
        lock (_lock)
        {
            return Task.FromResult(
                _notifications
                    .Where(n => n.Id > lastSeenId)
                    .OrderByDescending(n => n.Timestamp)
                    .ToList());
        }
    }

    private async Task GenerateNotificationsAsync()
    {
        var messages = new[]
        {
            "Someone liked your post.",
            "You have a new follower.",
            "Scheduled maintenance tonight at 11 PM.",
            "Your export is ready to download.",
            "A comment was added to your thread.",
            "Weekly summary is available.",
            "Security alert: new login detected.",
        };

        var rng = new Random();
        while (true)
        {
            await Task.Delay(TimeSpan.FromSeconds(rng.Next(8, 20)));
            lock (_lock)
            {
                _notifications.Add(new Notification
                {
                    Id = _nextId++,
                    Message = messages[rng.Next(messages.Length)],
                    Timestamp = DateTime.UtcNow,
                });
            }
        }
    }
}

@page "/notifications"
@rendermode InteractiveServer
@using NotificationsApp.Services
@inject NotificationService NotificationSvc
@implements IAsyncDisposable

<PageTitle>Notifications</PageTitle>

<h1>
    Notifications
    @if (notifications is not null)
    {
        <span class="badge">@notifications.Count</span>
    }
</h1>

@if (notifications is null)
{
    <p><em>Loading notifications…</em></p>
}
else if (notifications.Count == 0)
{
    <p>No notifications yet.</p>
}
else
{
    <ul class="notification-list">
        @foreach (var n in notifications)
        {
            <li>
                <span class="message">@n.Message</span>
                <span class="timestamp">@n.Timestamp.ToString("g")</span>
            </li>
        }
    </ul>
}

@code {
    private List<Notification>? notifications;
    private int lastSeenId;
    private CancellationTokenSource? cts;

    [PersistentState]
    public List<Notification>? PersistedNotifications { get; set; }

    protected override async Task OnInitializedAsync()
    {
        // On the interactive render, PersistedNotifications is restored automatically.
        // Only fetch from the service if state wasn't persisted (first prerender).
        if (PersistedNotifications is not null)
        {
            notifications = PersistedNotifications;
        }
        else
        {
            notifications = await NotificationSvc.GetNotificationsAsync();
            PersistedNotifications = notifications;
        }

        lastSeenId = notifications.Count > 0 ? notifications.Max(n => n.Id) : 0;
    }

    protected override void OnAfterRender(bool firstRender)
    {
        // OnAfterRender is never called during prerender, so the polling
        // loop only starts once the page is live and interactive.
        if (firstRender)
        {
            cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(cts.Token);
        }
    }

    private async Task PollForNotificationsAsync(CancellationToken ct)
    {
        while (!ct.IsCancellationRequested)
        {
            try
            {
                await Task.Delay(TimeSpan.FromSeconds(5), ct);

                var newer = await NotificationSvc.GetNotificationsSinceAsync(lastSeenId);
                if (newer.Count > 0 && notifications is not null)
                {
                    notifications.InsertRange(0, newer);
                    lastSeenId = newer.Max(n => n.Id);
                    await InvokeAsync(StateHasChanged);
                }
            }
            catch (TaskCanceledException)
            {
                break;
            }
        }
    }

    public async ValueTask DisposeAsync()
    {
        if (cts is not null)
        {
            await cts.CancelAsync();
            cts.Dispose();
        }
    }
}

